mapper.select:
SELECT * FROM batch_transfer_ledger
WHERE 1=1
AND operator LIKE CONCAT('%', #{operator}, '%')
AND transfer_time >= #{startTime}
AND transfer_time <= #{endTime}
AND batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND settle_status = #{settleStatus}
ORDER BY transfer_time DESC

mapper.update:
UPDATE batch_transfer_ledger
SET settle_status = 'CLOSED',
    settled_by = #{operator},
    settled_at = #{time}
WHERE id = #{id}
  AND settle_status = 'OPEN'
